'use strict';
const zh=document.documentElement.lang.startsWith('zh');
const T=(en,cn)=>zh?cn:en;
const protocol=window.CBWCE_PROTOCOL;
let data=window.CBWCE_DATA, token=null, mode='hosted', selected='train', catalog={checkpoints:[],gates:[],runs:[]}, currentJob=null;
let state={network:'grid',controller:'ia2c',method:'baseline',stage:'parent',seed:9001,pilot:true,visualization:true,parent:'',wce:'',resume:'',gate:'',steps:160,episodes:2,suite:'all',rollouts:10};
try{const saved=JSON.parse(localStorage.getItem('cbwce-settings')||'{}');Object.assign(state,saved);if(typeof saved.visualization!=='boolean')state.visualization=state.pilot;selected=location.hash.slice(1)||'train';}catch(e){}
const escapeHTML=x=>String(x==null?'':x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={train:T('Train & monitor','训练与监控'),study:T('Research & protocol','研究与实验方案'),files:T('Project structure','项目结构'),results:T('Results & plots','结果与图表'),checks:T('Readiness & checks','准备与验证'),story:T('Research comic','研究漫画')};
const stages={parent:T('I · Common parent','I · 公共父模型'),wce:T('II · Frozen-parent WCE','II · 冻结父模型训练 WCE'),continue:T('III · Continuation','III · 控制器续训'),evaluate:T('IV · Paired evaluation','IV · 配对评估')};
const methods={baseline:T('Original sequential profiles','原有顺序需求组'),random_group:T('One random profile per block','每个需求时段随机选一组'),domain_randomization:T('Dirichlet demand mixtures','Dirichlet 需求混合'),fixed_wce:T('State-dependent mixtures; frozen WCE parameters','根据状态生成混合需求；WCE 模型参数冻结'),online_wce:T('State-dependent mixtures; WCE learns each episode','根据状态生成混合需求；WCE 每回合学习')};
function save(){try{localStorage.setItem('cbwce-settings',JSON.stringify(state));}catch(e){}}
function options(values,value){return values.map(v=>{const a=Array.isArray(v)?v:[v,v];return `<option value="${escapeHTML(a[0])}" ${String(a[0])===String(value)?'selected':''}>${escapeHTML(a[1])}</option>`;}).join('');}
function select(id,label,values,value,wide=false){return `<label class="${wide?'wide':''}">${label}<select id="${id}">${options(values,value)}</select></label>`;}
function command(){let a=['python','main.py','experiment',state.stage,'--network',state.network,'--controller',state.controller,'--seed',state.seed];a.push(state.visualization?'--visualization':'--no-visualization');if(state.stage==='continue')a.push('--method',state.method);if(state.pilot){a.push('--pilot');if(['parent','continue'].includes(state.stage))a.push('--steps',state.steps);if(state.stage==='wce')a.push('--episodes',state.episodes);}for(const k of ['parent','wce','resume','gate'])if(state[k])a.push('--'+k,state[k]);if(state.stage==='evaluate')a.push('--suite',state.suite,'--rollouts',state.rollouts);return a.map(x=>/^[\w./:-]+$/.test(String(x))?x:"'"+String(x).replace(/'/g,"'\\''")+"'").join(' ');}
function shell(){document.getElementById('app').innerHTML=`<header><div><strong>CB-WCE <span style="color:#79dacd">/</span> ${T('Research workspace','研究工作台')}</strong><small>${T('Traffic signal control · Grid & Monaco','交通信号控制 · 网格与摩纳哥')}</small></div><div><span id="mode" class="badge">${T('Private guide','私有指南')}</span> &nbsp;<a id="language" href="${zh?'index.html':'zh.html'}#${selected}">${zh?'English':'简体中文'}</a></div></header><div class="shell"><nav aria-label="${T('Main navigation','主导航')}">${Object.entries(names).map(([k,v])=>`<button data-view="${k}">${v}</button>`).join('')}<p>${T('Protocol 3 · Five methods<br>Reproducibility before performance.','方案 3 · 五种方法<br>先验证实验机制，再比较性能。')}</p></nav><main id="content"></main></div>`;document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));render();}
function navigate(view){selected=names[view]?view:'train';location.hash=selected;document.getElementById('language').href=(zh?'index.html':'zh.html')+'#'+selected;render();}
function render(){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===selected));document.getElementById('mode').textContent=mode==='local'?T('Local launcher','本地启动器'):T('Private / offline guide','私有／离线指南');({train:trainView,study:studyView,files:filesView,results:resultsView,checks:checksView,story:storyView}[selected]||trainView)();}
function page(title,subtitle,body){document.getElementById('content').innerHTML=`<div class="topline"><div><h1>${title}</h1><p class="muted">${subtitle}</p></div><span class="badge warn">${T('Publication training not launched','完整论文训练尚未启动')}</span></div>${body}<footer>${T('Mean total queue on controlled approaches · Lower is better. Pilot observations are not publication comparisons.','受控进口道平均总排队车辆数 · 越低越好。试运行数据不能作为论文性能比较。')}</footer>`;}
function checkpointChoices(role){const extras=[state.parent,state.wce,state.resume].filter(p=>p&&!catalog.checkpoints.some(c=>c.path===p)).map(p=>[p,p]);return [['',T('Select an explicit checkpoint','选择明确的检查点')],...extras,...catalog.checkpoints.filter(c=>c.signatures[role]&&c.signatures[role].network===state.network&&(role==='wce'||c.signatures[role].family===state.controller)).map(c=>[c.path,c.path])];}
function checkpointField(id,label,role,value){return mode==='local'?select(id,label,checkpointChoices(role),value,true):`<label class="wide">${label}<input id="${id}" value="${escapeHTML(value)}" placeholder="${T('Exact local checkpoint path','准确的本地检查点路径')}"></label>`;}
function trainView(){const frozen=state.stage==='continue'&&['fixed_wce','online_wce'].includes(state.method);page(T('Train, challenge, evaluate','训练、挑战、评估'),T('Choose one stage. Review its inputs before starting a local job.','选择一个阶段。启动本地任务前检查输入。'),`<div class="workflow">${Object.entries(stages).map(([s,n])=>`<button data-stage="${s}"><b>${n}</b><span>${s==='parent'?'1,000,000 '+T('learning steps','训练步'):s==='wce'?'500 '+T('episodes · controller frozen','回合 · 控制器冻结'):s==='continue'?'+1,320,000 '+T('learning steps','训练步'):'23 × 10 '+T('paired rollouts','配对轨迹')}</span></button>`).join('')}</div><div class="grid"><section class="card"><h2>${T('Job settings','任务设置')}</h2><div class="fields">${select('stage',T('Stage','阶段'),Object.entries(stages),state.stage)}${select('pilot',T('Run type','运行类型'),[['true',T('Pilot · default','试运行 · 默认')],['false',T('Publication · gated','论文实验 · 需验证准入')]],String(state.pilot))}${select('visualization',T('SUMO visualization','SUMO 可视化'),[['false',T('Off · publication default','关闭 · 论文默认')],['true',T('On · pilot default','开启 · 试运行默认')]],String(state.visualization))}${select('network',T('Network','路网'),[['grid','5 × 5 Grid'],['monaco',T('Monaco subnet','摩纳哥子网')]],state.network)}${select('controller',T('Controller','控制器'),protocol.controllers,state.controller)}${select('method',T('Continuation method','续训方法'),protocol.methods,state.method)}${select('seed',T('Training seed','训练种子'),state.pilot?[9001,9002]:protocol.training_seeds,state.seed)}${state.pilot&&['parent','continue'].includes(state.stage)?`<label>${T('Pilot learning budget','试运行训练预算')}<input id="steps" type="number" min="1" value="${state.steps}"></label>`:''}${state.pilot&&state.stage==='wce'?`<label>${T('Pilot WCE episodes','试运行 WCE 回合')}<input id="episodes" type="number" min="1" value="${state.episodes}"></label>`:''}${state.stage!=='parent'?checkpointField('parent',T('Controller checkpoint','控制器检查点'),'controller',state.parent):''}${frozen?checkpointField('wce',T('Pretrained WCE checkpoint','预训练 WCE 检查点'),'wce',state.wce):''}${checkpointField('resume',T('Resume checkpoint (optional)','恢复检查点（可选）'),'controller',state.resume)}${!state.pilot?(mode==='local'?select('gate',T('Current verification gate','当前验证准入记录'),[['',T('Select passing gate','选择已通过记录')],...catalog.gates],state.gate,true):checkpointField('gate',T('Current verification gate','当前验证准入记录'),'controller',state.gate)):''}${state.stage==='evaluate'?select('suite',T('Evaluation scenarios','评估场景'),[['all',T('11 seen + 12 new','11 个已见 + 12 个新场景')],['seen',T('Seen profiles','已见需求组')],['test',T('New scenarios','新场景')],['validation',T('Validation only','仅验证集')]],state.suite,true):''}</div><p class="muted">${T('Pilot mode selects visualization On; publication mode selects Off. You can override that choice. Visualization opens a separate SUMO window on the training computer and starts playback automatically. Choose before launch; it cannot switch a running job. A desktop display and sumo-gui are required. Leave it off for timed study runs.','选择试运行时默认开启可视化，选择论文实验时默认关闭；可以手动更改。可视化会在训练电脑上打开独立 SUMO 窗口并自动播放。请在启动前选择；运行中不能切换。需要桌面显示环境和 sumo-gui。计时实验请保持关闭。')}</p><p class="muted">${methods[state.method]}</p><div class="actions"><button id="preflight">${T('Check & preview','检查并预览')}</button><button class="primary" id="start" ${mode!=='local'?'disabled':''}>${T('Start selected job','启动所选任务')}</button><button id="refresh">${T('Refresh checkpoints','刷新检查点')}</button></div><div id="notice"></div></section><section><div class="card"><h2>${T('Command & output','命令与输出')}</h2><pre id="command">${escapeHTML(command())}</pre><button id="copy">${T('Copy command','复制命令')}</button><p id="resolved" class="muted"></p>${mode!=='local'?`<div class="message">${T('Training runs on your computer. Open the local launcher:','训练在你的电脑上执行。打开本地启动器：')}<pre>conda activate deeprlsc\npython main.py experiment dashboard</pre><a href="http://127.0.0.1:8765/">${T('Open local workspace','打开本地工作台')}</a></div>`:''}</div><div class="card"><h2>${T('Current job','当前任务')}</h2><div id="job">${T('No job started in this session.','本次会话尚未启动任务。')}</div><div class="actions"><button class="danger" id="stop" ${mode!=='local'?'disabled':''}>${T('Stop job','停止任务')}</button><button id="resumeJob" ${mode!=='local'?'disabled':''}>${T('Use last checkpoint','使用最后检查点')}</button></div></div></section></div>`);
 document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{state.stage=b.dataset.stage;state.parent='';state.wce='';state.resume='';state.steps=state.stage==='parent'?160:2640;save();render();});
 for(const id of ['stage','pilot','visualization','network','controller','method','seed','steps','episodes','parent','wce','resume','gate','suite']){const e=document.getElementById(id);if(e)e.onchange=()=>{state[id]=['seed','steps','episodes'].includes(id)?Number(e.value):['pilot','visualization'].includes(id)?e.value==='true':e.value;if(id==='pilot'){state.seed=state.pilot?9001:101;state.visualization=state.pilot;}if(id==='stage')state.steps=state.stage==='parent'?160:2640;if(['stage','network','controller','method'].includes(id)){state.resume='';if(id!=='method')state.parent='';state.wce='';}save();render();};}
 for(const id of ['steps','episodes']){const e=document.getElementById(id);if(e)e.oninput=()=>{state[id]=Number(e.value);save();document.getElementById('command').textContent=command();};}
 document.getElementById('method').disabled=state.stage!=='continue';
 document.getElementById('copy').onclick=async()=>{try{await navigator.clipboard.writeText(command());notice(T('Command copied.','命令已复制。'));}catch(e){notice(T('Select the command text and copy it manually.','请选择命令文本并手动复制。'));}};
 document.getElementById('preflight').onclick=async()=>{if(mode!=='local'){notice(T('Command prepared. Full checkpoint validation runs in the local workspace.','命令已准备。完整检查点验证将在本地工作台执行。'));return;}try{const r=await api('/api/preflight',spec());document.getElementById('command').textContent=r.command;document.getElementById('resolved').textContent=r.output;notice(T('Inputs accepted. Review the command, then start.','输入检查通过。确认命令后可启动。'));}catch(e){notice(e.message);}};
 document.getElementById('start').onclick=async()=>{try{currentJob=await api('/api/jobs',spec());showJob();}catch(e){notice(e.message);}};document.getElementById('refresh').onclick=refresh;
 document.getElementById('stop').onclick=async()=>{try{currentJob=await api('/api/stop',{});showJob();}catch(e){notice(e.message);}};
 document.getElementById('resumeJob').onclick=()=>{if(currentJob&&currentJob.checkpoint){state.resume=currentJob.checkpoint;save();render();}else notice(T('No complete checkpoint is available yet.','尚无完整检查点。'));};showJob();}
function spec(){const s={...state};if(s.stage==='parent'){delete s.parent;delete s.wce;}if(s.stage!=='continue'||!['fixed_wce','online_wce'].includes(s.method))delete s.wce;if(!s.pilot){delete s.steps;delete s.episodes;}if(s.stage!=='evaluate'){delete s.suite;delete s.rollouts;}return s;}
function notice(text){const e=document.getElementById('notice');if(e)e.innerHTML=`<div class="message">${escapeHTML(text)}</div>`;}
function showJob(){const el=document.getElementById('job');if(!el||!currentJob||currentJob.status==='idle')return;const p=currentJob.progress||{};el.innerHTML=`<span class="badge">${escapeHTML(currentJob.status)}</span><div class="metricrow"><div><strong>${(p.learning_steps||0).toLocaleString()}</strong><span>${T('learning steps','训练步')}</span></div><div><strong>${Math.round(currentJob.elapsed_seconds||0)} s</strong><span>${T('elapsed','已用时间')}</span></div><div><strong>${p.wce_updates||0}</strong><span>${T('WCE updates','WCE 更新')}</span></div></div><progress value="${p.simulation_steps||0}" max="${p.goal||1}"></progress><p class="muted">${escapeHTML(currentJob.output)}</p><pre>${escapeHTML(currentJob.log||'')}</pre>`;}
function table(headers,rows){return `<div class="tablewrap"><table><thead><tr>${headers.map(h=>`<th>${escapeHTML(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${escapeHTML(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function trafficGenerationSection(){return `<section class="card" id="traffic-generation"><h2>${T('How validation and test traffic are generated','验证与测试交通如何生成')}</h2><p>${T('Both networks use the same procedure with their own OD profiles and road geometry. These are predefined synthetic demand scenarios, not new field measurements or WCE-generated test traffic.','两个路网使用相同流程，但各自采用本路网的 OD 配置和道路几何。这些是预定义合成需求场景，不是新实测数据或 WCE 生成的测试交通。')}</p>${table([T('Network','路网'),T('Reference rate','参考需求率'),T('Dataset root','数据集根目录')],[['Grid','3,000 veh/hour','data_traffic/revised/'],['Monaco','2,383.3333 veh/hour','real_net_subnet/demand_groups/revised/']])}<details open><summary>${T('1 · Define the held-out demand scenarios','1 · 定义留出的需求场景')}</summary><p>${T('Normalize eleven source profiles to the reference rate, preserving OD proportions. Redistribution multiplies Uniform OD rates by lognormal factors then restores the total. Mixtures combine all profiles with one fixed vector for the entire hour. Switching starts N_to_S and alternates W_to_E. Peaks affect only [1200,2400); all scenarios last 3600 seconds.','将十一种原始配置归一化到参考率，保留 OD 比例。重分配对 Uniform OD 需求率乘对数正态因子后恢复总量；混合用一个固定向量组合全部配置，整小时保持不变。切换从 N_to_S 开始，与 W_to_E 交替；高峰仅作用于 [1200,2400)，所有场景持续 3600 秒。')}</p>${table([T('Family','类别'),T('Test / generation seeds','测试／生成种子'),T('Validation / generation seeds','验证／生成种子')],[[T('OD redistribution','OD 重分配'),'σ = 0.25 / 0.50 / 0.75; 41001–41003','σ = 0.35 / 0.65; 31001–31002'],[T('Fixed Dirichlet mixtures','固定 Dirichlet 混合'),'3; 41004–41006','2; 31003–31004'],[T('Directional switching','方向切换'),'300 / 900 / 1200 s; 41007–41009','450 s; 31005'],[T('Uniform peak multiplier','Uniform 高峰倍数'),'1.10 / 1.25 / 1.50; 41010–41012','1.15; 31006']])}<p>${T('Mixture weights follow each network’s train/manifest.json order: alphabetical in Grid, explicit ORDER in Monaco. New mixtures test composition within the WCE-accessible family; they are not automatically out-of-distribution demand.','混合权重采用各路网 train/manifest.json 的顺序：Grid 为字母序，Monaco 为显式 ORDER。新混合测试 WCE 可访问需求族内的组合，不自动等于分布外需求。')}</p></details><details><summary>${T('2 · Sample actual vehicles and freeze their routes','2 · 抽取车辆并固定完整路径')}</summary><ol><li>${T('Resolve each positive-rate OD route on the corresponding SUMO network, even before a zero-count draw can occur. Reject unreachable routes.','先在对应 SUMO 路网解析每个正需求 OD 的路径，即使随后可能抽到零辆车也要验证；拒绝不可达路径。')}</li><li>${T('Draw Poisson counts with mean rate × block_seconds / 3600. Draw departures uniformly in the block, add normal jitter (SD 2 seconds), clip inside its boundaries by 0.01 seconds and round to two decimals.','按均值 rate × block_seconds / 3600 抽取泊松车辆数；区间内均匀抽取出发时间，加标准差 2 秒的正态扰动，裁剪至距边界 0.01 秒处，再保留两位小数。')}</li><li>${T('Sample a positive speed factor from a normal distribution (mean 1, SD 0.1), redrawing nonpositive values. Save each vehicle’s ID, departure, OD pair, full edge route and speed factor in JSON.','从均值 1、标准差 0.1 的正态分布抽取正速度因子，非正值重新抽样。将每辆车的 ID、出发时间、OD 对、完整道路路径和速度因子保存到 JSON。')}</li></ol><p>${T('Example: Grid peak_1.25 requests 3000 → 3750 → 3000 veh/hour over three 20-minute blocks: 3250 expected vehicles. Its existing arrival-seed-51001 artifact contains 3335. Monaco has about 2581.9444 expected and 2632 scheduled. These are input counts, not controller performance.','示例：Grid peak_1.25 在三个 20 分钟区间请求 3000 → 3750 → 3000 veh/hour，期望 3250 辆；已有到达种子 51001 文件安排 3335 辆。Monaco 期望约 2581.9444 辆，安排 2632 辆。这些是输入数量，不是控制器性能。')}</p></details><details><summary>${T('3 · Pair the ten realizations and keep splits separate','3 · 配对十次实现并分离数据集')}</summary><p>${T('Arrival seeds 51001–51010 control counts, departures and speed factors. SUMO seeds 61001–61010 control simulation randomness; policy seeds control actions separately. Generation seeds randomize redistribution/mixtures; for deterministic switch/peak schedules they are identifiers. Arrival seeds are reused across scenarios, splits and networks, so validation/test arrivals do not have wholly disjoint random streams.','到达种子 51001–51010 控制数量、出发时间和速度因子；SUMO 种子 61001–61010 控制仿真随机性，策略种子独立控制动作。生成种子用于随机重分配／混合；在确定性切换／高峰计划中只是标识。到达种子跨场景、划分和路网复用，因此验证／测试到达并非完全不重叠的随机流。')}</p><p>${T('Reuse the exact same artifact hash across compared methods for each network/scenario/arrival realization. Actual insertion may differ with congestion. Validation supports development; keep final test results out of parameter and checkpoint selection.','同一路网／场景／到达实现下，各方法复用完全相同的文件哈希；拥堵可以改变实际插入。验证用于开发，最终测试结果不参与参数或检查点选择。')}</p>${table([T('Split','划分'),T('Scenarios per network','每路网场景数'),T('Saved schedules','已保存计划')],[['validation',6,60],['test',12,120],['seen',11,110]])}<p>${T('290 artifacts per network, 580 total. --suite all means 11 seen + 12 test; validation is separate. Seen artifacts live under test/artifacts/ but carry scenario.split = seen.','每路网 290 份，共 580 份。--suite all 指 11 项已见 + 12 项测试，验证单独使用。已见文件位于 test/artifacts/，但其 scenario.split = seen。')}</p></details><details><summary>${T('4 · Commands, files and responsible scripts','4 · 命令、文件与负责脚本')}</summary><pre>python main.py experiment prepare
python main.py experiment prepare --materialize --network grid
python main.py experiment prepare --materialize --network monaco</pre><p>${T('Materialization starts SUMO for route resolution; it does not train a controller. Existing matching artifacts are reused and conflicting inputs are rejected. Each dataset stores validation/validation_scenarios.json, test/test_scenarios.json and test/seen_scenarios.json; complete vehicles are in each split’s artifacts/&lt;scenario&gt;_&lt;arrival_seed&gt;.json.','物化启动 SUMO 解析路径，不训练控制器；匹配的已有文件会复用，冲突输入会被拒绝。各数据集保存 validation/validation_scenarios.json、test/test_scenarios.json、test/seen_scenarios.json；完整车辆位于各划分的 artifacts/&lt;scenario&gt;_&lt;arrival_seed&gt;.json。')}</p><p><code>experiments/prepare.py → experiments/scenarios.py → experiments/demand.py → envs/experiment_env.py</code></p><p>${T('Test construction is in scenarios.py; validation parameters and seed lists are in config/revised/protocol.json. Preserve frozen inputs when revising a protocol.','测试构造位于 scenarios.py；验证参数和种子列表位于 config/revised/protocol.json。修订方案时应保留冻结的旧输入。')}</p></details></section>`;}

function studyView(){page(T('A controller that learns to handle changing demand','学习应对变化需求的交通控制器'),T('The hypothesis: challenging training demand may improve robustness. The evaluation tests that hypothesis.','研究假设：具有挑战性的训练需求可能提升鲁棒性。通过评估检验这一假设。'),`<div class="grid"><section class="card"><h2>${T('Research idea','研究思路')}</h2><p>${T('A traffic-signal controller learns when to change lights. CB-WCE observes traffic and learns mixtures of eleven demand profiles that increase queue cost. We freeze a trained controller to learn the initial WCE, then compare five equally budgeted continuations.','交通信号控制器学习何时切换信号。CB-WCE 观察交通状态，学习能够提高排队成本的十一种需求组混合方式。先冻结已训练控制器以训练初始 WCE，再比较五种训练预算相同的续训方法。')}</p><p class="tabsnote">${T('Fixed WCE means fixed model parameters. Its demand-mixture weights may still change with traffic state. Online WCE also updates model parameters after each episode.','固定 WCE 指模型参数固定。它的需求混合权重仍可随交通状态变化。在线 WCE 还会在每个回合结束后更新模型参数。')}</p>${table([T('Method','方法'),T('Demand selection','需求选择')],Object.entries(methods))}</section><section class="card"><h2>${T('Execution order','执行顺序')}</h2><ol><li>${T('Prepare normalized inputs and pass all ten correction checks.','准备归一化输入并通过全部十项修正检查。')}</li><li>${T('Train 40 independent parents, each for 1,000,000 learning steps.','训练 40 个独立父模型，每个训练 1,000,000 步。')}</li><li>${T('Train 40 WCE models for 500 episodes each against frozen parents.','针对冻结父模型训练 40 个 WCE，每个 500 回合。')}</li><li>${T('Branch each parent into five methods. Each adds 1,320,000 learning steps.','每个父模型分为五种方法，每种增加 1,320,000 训练步。')}</li><li>${T('Evaluate exact final checkpoints with paired traffic on 11 seen and 12 new scenarios.','在 11 个已见和 12 个新场景上，用配对交通评估精确最终预算检查点。')}</li></ol>${table([T('Controller','控制器'),'LR',T('Grid batch','网格批长度'),T('Monaco batch','摩纳哥批长度')],[['IA2C',.0005,120,40],['MA2C',.0005,120,40],['IQL-LR',.0001,20,20],['PPO',.0003,120,120]])}</section></div><section class="card"><h2>${T('Measurement contract','测量定义')}</h2><pre>Q(t) = Σ q_lane(t)\nJ_Q = (1/H) Σ Q(t)\nr_WCE = mean(Q over 600 seconds) / 100</pre><p>${T('Uncapped stopped vehicles, sampled every second on 150 Grid or 116 Monaco controlled incoming lanes. Controller rewards are negative queue costs scaled once by 100. WCE maximizes positive queue cost. Controller actions last 5 seconds; training episodes last 6,600 seconds.','对网格 150 条或摩纳哥 116 条受控进口车道，每秒采集无上限的停车车辆数。控制器奖励为负排队成本，且仅除以 100 一次。WCE 最大化正排队成本。控制器动作持续 5 秒，训练回合持续 6,600 秒。')}</p>${table([T('Test family','测试类别'),T('Settings','设置')],[[T('OD redistribution','OD 需求率重分配'),'σ = 0.25, 0.50, 0.75'],[T('Convex mixtures','凸组合混合'),'Dirichlet(1,…,1) × 3'],[T('Temporal switching','时间切换'),'300 / 900 / 1200 s'],[T('Peak demand','高峰需求'),'1.10× / 1.25× / 1.50×; [1200,2400) s']])}</section>${trafficGenerationSection()}`);}
const folders=[['agents/',T('Policies, corrected controller and WCE learning, recurrent networks.','策略、修正控制器与 WCE 学习、循环网络。')],['envs/',T('Original environments plus the integrated SUMO measurement path.','原有环境以及集成的 SUMO 测量流程。')],['experiments/',T('Protocol, runners, datasets, checkpoints, reports, and local launcher.','实验方案、运行器、数据集、检查点、报告和本地启动器。')],['revision/',T('Compatibility wrappers and preserved verification evidence.','兼容入口与保留的验证证据。')],['config/revised/',T('Effective controller configurations and protocol.json.','生效的控制器配置和 protocol.json。')],['data_traffic/revised/ · real_net_subnet/demand_groups/revised/',T('Separate train/, validation/, test/ inputs and immutable traffic artifacts.','独立的 train/、validation/、test/ 输入与不可变交通文件。')],['runs/revised/',T('Common parents and baseline continuations.','公共父模型与基线续训。')],['output_adversary/revised/ · output_adversary_monaco/revised/',T('Frozen-parent WCE training outputs by network.','按路网保存冻结父模型 WCE 训练输出。')],['output_coevolution/revised/ · output_coevolution_real/revised/',T('Four comparison continuations by network.','按路网保存四种比较方法续训。')],['runs_eval/revised/',T('Evaluation attempts, verification records, and local job logs.','评估尝试、验证记录与本地任务日志。')],['output_result/revised/ · figs/revised/',T('Scientific tables, dashboard exports, curves, and heatmaps.','科学统计表、仪表板导出、曲线与热力图。')],['docs/history/ · docs/site/',T('Preserved original files and this bilingual workspace.','保留的原始文件与双语工作台。')],['Existing folders and root scripts',T('Historical files stay at their original paths. Old training entrypoints use the legacy workflow.','历史文件保留原路径。旧训练入口仍使用历史流程。')]];
function filesView(){page(T('Familiar folders, one corrected workflow','熟悉的目录，统一的修正流程'),T('Expand a folder to see what belongs there. Historical files are preserved.','展开目录查看用途。历史文件均保留。'),`<section class="card">${folders.map(([p,d])=>`<details><summary><code>${p}</code></summary><p>${d}</p></details>`).join('')}</section><section class="card"><h2>${T('Output naming','输出命名')}</h2><pre>&lt;stage-root&gt;/&lt;network&gt;/&lt;controller&gt;/seed_&lt;seed&gt;/&lt;stage-or-method&gt;/&lt;run_id&gt;/</pre><p>${T('Every run has an immutable manifest. Evaluation adds split/scenario/rollout/attempt identifiers. A resume creates a separate attempt; previous files are retained.','每次运行包含不可变清单。评估增加数据集划分、场景、轨迹及尝试标识。恢复会创建独立尝试，并保留以前的文件。')}</p></section>`);}
function chart(points,x,y,label){if(!points.length)return `<div class="statusempty">${T('No recorded curve for this selection.','该选择暂无记录曲线。')}</div>`;const w=700,h=280,pad=48,xs=points.map(p=>Number(p[x])),ys=points.map(p=>Number(p[y])),xmin=Math.min(...xs),xmax=Math.max(...xs),ymax=Math.max(...ys,1),poly=points.map((p,i)=>`${pad+(xs[i]-xmin)/(xmax-xmin||1)*(w-pad*2)},${h-pad-ys[i]/ymax*(h-pad*2)}`).join(' ');return `<svg class="chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="${escapeHTML(label)}"><line x1="48" y1="232" x2="652" y2="232"/><line x1="48" y1="48" x2="48" y2="232"/><polyline points="${poly}" fill="none" stroke="#007982" stroke-width="2.5"/><text x="48" y="260">${xmin}</text><text x="585" y="260">${xmax}</text><text x="5" y="48">${ymax.toFixed(0)}</text><text x="100" y="24">${escapeHTML(label)}</text></svg>`;}
function installRunPicker(){if(mode!=='local')return;const section=document.createElement('section');section.className='card';section.innerHTML='<h2>'+T('Local run records','本地运行记录')+'</h2><p>'+T('Select explicit run attempts to generate a report.','选择明确的运行尝试以生成报告。')+'</p><div class="tablewrap"><table><thead><tr><th></th><th>'+T('Run','运行')+'</th><th>'+T('Stage / method','阶段／方法')+'</th><th>'+T('Status','状态')+'</th></tr></thead><tbody>'+catalog.runs.map((r,i)=>'<tr><td><input type="checkbox" data-run="'+i+'" aria-label="'+escapeHTML(r.path)+'"></td><td><code>'+escapeHTML(r.path)+'</code></td><td>'+escapeHTML(r.stage+' / '+r.method)+'</td><td>'+escapeHTML(r.status)+'</td></tr>').join('')+'</tbody></table></div><div class="actions"><button id="buildReport">'+T('Report selected attempts','为所选尝试生成报告')+'</button></div><p id="reportMessage"></p>';document.getElementById('content').appendChild(section);document.getElementById('buildReport').onclick=async()=>{const inputs=[...section.querySelectorAll('[data-run]:checked')].map(e=>catalog.runs[Number(e.dataset.run)].path);try{const r=await api('/api/report',{inputs});data=r.data;resultsView();}catch(e){document.getElementById('reportMessage').textContent=e.message;}};}
function resultsView(){const rows=data.rollouts||[];page(T('Evidence, with its experimental context','带有实验背景的证据'),T('Import a dashboard.json export or inspect bundled pilot records.','导入 dashboard.json 导出文件，或查看附带的试运行记录。'),`<section class="card"><div class="actions"><label>${T('Load local result export','载入本地结果导出')}<input type="file" id="import" accept=".json"></label><button id="export">${T('Download current data','下载当前数据')}</button></div><div class="filters">${select('filterNetwork',T('Network','路网'),[['all',T('All networks','全部路网')],...protocol.networks],'all')}${select('filterController',T('Controller','控制器'),[['all',T('All controllers','全部控制器')],...protocol.controllers],'all')}${select('filterType',T('Evidence','证据'),[['pilot',T('Pilot only','仅试运行')],['publication',T('Publication only','仅论文实验')]],'pilot')}</div><div id="resultTable"></div></section><section class="card"><h2>${T('Queue through training','训练期间的排队曲线')}</h2><div id="curve"></div></section><section class="card"><h2>${T('Peak-demand lane maps','高峰需求车道图')}</h2><div id="heatmap"></div><p>${T('Same monitored lanes and [1200,2400) window. Negative online-minus-comparator values mean lower queues under online WCE.','使用相同受控车道与 [1200,2400) 时间窗口。在线减去比较方法的负值表示在线 WCE 排队更低。')}</p></section><section class="card"><h2>${T('Publication uncertainty','论文实验不确定性')}</h2><p>${T('Each scenario uses ten rollout outcomes. The primary new-demand result gives equal weight to twelve scenarios within each training seed, then reports five-seed SD and a 95% t-interval. Missing cells remain incomplete.','每个场景使用十次轨迹结果。主要新需求结果先在每个训练种子内对十二个场景等权平均，再报告五个种子的标准差与 95% t 区间。缺失单元保持未完成状态。')}</p><div id="uncertainty"></div></section>`);
 const update=()=>{const n=document.getElementById('filterNetwork').value,c=document.getElementById('filterController').value,p=document.getElementById('filterType').value==='pilot';const match=r=>(n==='all'||r.network===n)&&(c==='all'||r.controller===c)&&!!r.pilot===p;const rr=rows.filter(match);document.getElementById('resultTable').innerHTML=rr.length?table([T('Network','路网'),T('Controller','控制器'),T('Method','方法'),T('Scenario','场景'),T('Seed','种子'),T('Mean queue','平均排队')],rr.slice(0,200).map(r=>[r.network,r.controller,r.method,r.scenario,r.seed,r.mean_queue.toFixed(3)])):`<div class="statusempty">${T('No completed observations for this selection.','该选择尚无完整观测记录。')}</div>`;const curves=(data.curves||[]).filter(match);document.getElementById('curve').innerHTML=curves.length?select('curveSelect',T('Training record','训练记录'),curves.map((v,i)=>[String(i),v.network+' / '+v.controller+' / '+v.method+' / '+v.stage]),'0')+'<div id="curvePlot"></div>':chart([],'learning_steps','mean_queue','');if(curves.length){const plot=()=>chart(curves[Number(document.getElementById('curveSelect').value)].points,'learning_steps','mean_queue',T('Mean total queue vs controller-learning steps','平均总排队与控制器训练步'));const redraw=()=>{document.getElementById('curvePlot').innerHTML=plot();};document.getElementById('curveSelect').onchange=redraw;redraw();}const maps=(data.heatmaps||[]).filter(match);document.getElementById('heatmap').innerHTML=maps.length?`${select('mapScenario',T('Map scenario','地图场景'),maps.map((v,i)=>[String(i),v.network+' / '+v.controller+' / '+v.scenario]),'0')}<select id="mapMethod" aria-label="${T('Map comparison','地图比较')}">${options([...protocol.methods,...protocol.methods.filter(m=>m!=='online_wce').map(m=>['online_minus_'+m,'online_wce − '+m])],'online_wce')}</select><div id="laneMap"></div>`:`<div class="statusempty">${T('Peak maps appear when paired scenario measurements are available.','获得配对场景测量数据后显示高峰图。')}</div>`;if(maps.length){const draw=()=>drawMap(maps[Number(document.getElementById('mapScenario').value)],document.getElementById('mapMethod').value);document.getElementById('mapMethod').onchange=draw;document.getElementById('mapScenario').onchange=draw;draw();}const complete=(data.comparisons||[]).filter(r=>r.complete&&(n==='all'||r.network===n)&&(c==='all'||r.controller===c));document.getElementById('uncertainty').innerHTML=complete.length?table([T('Network','路网'),T('Controller','控制器'),T('Method','方法'),T('Split','数据集'),T('Mean','均值'),T('SD','标准差'),'95% ±'],complete.map(r=>[r.network,r.controller,r.method,r.split,r.mean,r.sd,r.ci95])):`<div class="statusempty">${T('Five complete publication training seeds are required.','需要五个完整的论文实验训练种子。')}</div>`;};let remembered={};try{remembered=JSON.parse(localStorage.getItem('cbwce-results-filters')||'{}');}catch(e){}['filterNetwork','filterController','filterType'].forEach(id=>{const e=document.getElementById(id);if(remembered[id]&&[...e.options].some(o=>o.value===remembered[id]))e.value=remembered[id];e.onchange=()=>{remembered[id]=e.value;try{localStorage.setItem('cbwce-results-filters',JSON.stringify(remembered));}catch(err){}update();};});update();document.getElementById('import').onchange=async e=>{try{const obj=JSON.parse(await e.target.files[0].text());if(!Array.isArray(obj.rollouts)||!Array.isArray(obj.comparisons))throw Error('Invalid dashboard export');data=obj;resultsView();}catch(err){alert(err.message);}};document.getElementById('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download='dashboard.json';a.click();URL.revokeObjectURL(a.href);};installRunPicker();const downloads=document.createElement('section');downloads.className='card';downloads.innerHTML='<h2>'+T('Download pilot figures','下载试运行图表')+'</h2><div class="actions"><a href="assets/figures/grid_iqll_peak_1.25_pilot_online_wce.png" download>Grid · PNG</a><a href="assets/figures/monaco_iqll_peak_1.25_pilot_online_wce.png" download>Monaco · PNG</a><a href="assets/figures/grid_iqll_peak_1.25_pilot_online_minus_baseline.svg" download>Grid · '+T('difference SVG','差值 SVG')+'</a><a href="assets/figures/monaco_iqll_peak_1.25_pilot_online_minus_baseline.svg" download>Monaco · '+T('difference SVG','差值 SVG')+'</a></div>';document.getElementById('content').appendChild(downloads);}
function drawMap(map,method){const pts=Object.values(map.geometry).flat(),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),scale=Math.min(650/(xmax-xmin),260/(ymax-ymin));document.getElementById('laneMap').innerHTML=`<svg class="chart" viewBox="0 0 700 300" role="img" aria-label="${escapeHTML(map.scenario)}">${map.lanes.map((l,i)=>{const diff=method.startsWith('online_minus_'),value=diff?map.values.online_wce[i]-map.values[method.slice(13)][i]:map.values[method][i],color=diff?`hsl(${value<0?215:8},70%,${95-50*Math.abs(value)/map.difference_max}%)`:`hsl(${185-145*value/map.absolute_max},75%,40%)`;return `<polyline points="${map.geometry[l].map(p=>`${25+(p[0]-xmin)*scale},${280-(p[1]-ymin)*scale}`).join(' ')}" stroke="${color}" fill="none" stroke-width="3"><title>${escapeHTML(l)}: ${value.toFixed(2)}</title></polyline>`;}).join('')}</svg><p>${escapeHTML(map.scenario)} · ${map.pairs} ${T('paired observations','配对观测')} · ${method.startsWith('online_minus_')?'±'+map.difference_max.toFixed(2):'0–'+map.absolute_max.toFixed(2)} ${T('vehicles/lane','车辆／车道')}</p>`;}
const checks=[['C01',T('Effective evaluation seeds','实际评估种子')],['C02',T('Independent RNG and paired traffic artifacts','独立随机流与配对交通文件')],['C03',T('Shared reward construction','统一奖励构造')],['C04',T('MA2C fingerprints and recurrent resets','MA2C 指纹与循环状态重置')],['C05',T('IQL learning every 20 new transitions','IQL 每 20 个新训练转移学习')],['C06',T('Correct Monaco IQL interfaces','正确的摩纳哥 IQL 接口')],['C07',T('Uncapped one-second queue measurements','无上限的每秒排队测量')],['C08',T('Complete checkpoints and masked partial batches','完整检查点与带掩码的部分批次')],['C09',T('Reject incomplete rollouts','拒绝不完整轨迹')],['C10',T('Immutable provenance and separate attempts','不可变来源记录与独立尝试')]];
function checksView(){page(T('Verify the mechanics first','先验证实验机制'),T('A historical passing gate does not certify changed code.','历史通过记录不能证明修改后的代码已通过验证。'),`<div class="grid"><section class="card"><h2>${T('Runtime preparation','运行环境准备')}</h2><pre>conda activate deeprlsc\npython main.py experiment prepare\npython main.py experiment check\npython main.py experiment verify --workers 4</pre><p>${T('Use Python 3.6.13 and the existing TensorFlow 1.12 runtime. SUMO requires local TraCI sockets. Publication jobs require a gate matching current code and inputs.','使用 Python 3.6.13 和现有 TensorFlow 1.12 运行环境。SUMO 需要本地 TraCI 连接。论文任务必须提供匹配当前代码和输入的验证准入记录。')}</p><button id="checkRuntime">${T('Check local runtime','检查本地运行环境')}</button><pre id="runtime">${T('Open the local workspace to inspect this computer.','打开本地工作台以检查这台电脑。')}</pre></section><section class="card">${table([T('Check','检查'),T('Required behavior','必需行为')],checks)}</section></div>`);document.getElementById('checkRuntime').onclick=async()=>{if(mode!=='local')return;try{document.getElementById('runtime').textContent=JSON.stringify(await api('/api/check'),null,2);}catch(e){document.getElementById('runtime').textContent=e.message;}};appendVerification();}
function appendVerification(){const v=window.CBWCE_VERIFICATION;if(!v)return;const panel=document.createElement('section');panel.className='card';panel.innerHTML='<h2>'+T('Recorded verification · '+v.date,'已记录验证 · '+v.date)+'</h2><p>'+T('Eight integrated SUMO cases passed C01–C10. The final 18-test suite and one additional evaluation checked the last identity, timer and reporting fixes.','八组集成 SUMO 试运行均通过 C01–C10。最终 18 项测试及一条附加评估验证了最后的身份、计时和报告修正。')+'</p>'+table([T('Network','路网'),T('Controller','控制器'),T('Status','状态'),T('Methods','方法数'),T('Pilot final steps','试运行最终步数')],v.cases.map(c=>[c.network,c.controller,T('Passed','通过'),c.methods,c.final_steps]))+'<p>'+T('This is a historical snapshot. The visualization update changes source hashes; run verification again before publication. Local preflight checks the selected gate against current source and inputs.','这是历史验证快照。可视化更新改变了源代码哈希；论文训练前请重新验证。本地启动前会核对所选准入文件与当前源代码及输入。')+'</p><a href="data/verification.json" download>'+T('Download verification summary','下载验证摘要')+'</a>';document.getElementById('content').appendChild(panel);}
function storyView(){page(T('The research, in six panels','六格漫画解释研究'),T('A visual explanation of the hypothesis and fair experimental comparison.','用图像解释研究假设与公平实验比较。'),`<section class="card"><img class="comic" src="assets/cbwce-comic-${zh?'zh':'en'}-v1.png" alt="${T('Six-panel comic: changing traffic, parent training, frozen-parent WCE, five branches, equal retraining budgets, and held-out evaluation.','六格漫画：交通变化、父模型训练、冻结父模型训练 WCE、五种分支、等预算续训及留出评估。')}"><div class="actions"><a download href="assets/cbwce-comic-${zh?'zh':'en'}-v1.png">${T('Download comic','下载漫画')}</a><a href="assets/transcripts-v1.json">${T('Read both transcripts','阅读双语文字稿')}</a></div></section>`);}
async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{'X-Session-Token':token||'','Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);return d;}
async function refresh(){if(mode!=='local')return;try{catalog=await api('/api/runs');render();}catch(e){notice(e.message);}}
shell();
if(['localhost','127.0.0.1'].includes(location.hostname)){fetch('/api/session').then(r=>r.json()).then(async s=>{token=s.token;mode='local';await refresh();}).catch(()=>{});}
setInterval(async()=>{if(mode==='local'){try{currentJob=await api('/api/job');showJob();}catch(e){}}},2500);
if(document.modelContext&&document.modelContext.registerTool){const ctx=document.modelContext;ctx.registerTool({name:'configure_training_view',description:'Select the visible training form; does not launch a job.',inputSchema:{type:'object',properties:{network:{enum:protocol.networks},controller:{enum:protocol.controllers}},additionalProperties:false},execute:input=>{if(input.network&&!protocol.networks.includes(input.network)||input.controller&&!protocol.controllers.includes(input.controller))throw Error('Invalid selection');Object.assign(state,input);save();navigate('train');return {network:state.network,controller:state.controller};}});ctx.registerTool({name:'read_training_status',description:'Read local job state without launching or stopping anything.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({mode,job:currentJob?{status:currentJob.status,progress:currentJob.progress}:null})});}
